/**
 * Taller input box — raises the message editor's height ceiling to a configurable
 * fraction of the terminal (default 60%, vs. the built-in 30%).
 *
 * @module taller-input
 *
 * Sources this was built from (paths under the pi install root,
 * /opt/homebrew/lib/node_modules/@earendil-works/pi-coding-agent):
 *
 * - node_modules/@earendil-works/pi-tui/dist/components/editor.js:374 — base
 *   `Editor.render()` caps visible height at `max(5, floor(terminalRows * 0.3))`,
 *   reading `this.tui.terminal.rows`. Hardcoded, no setting. The `─── ↑ N more`
 *   indicator (editor.js:396, :453) shows once content exceeds the cap. The same
 *   0.3 also sets the PageUp/PageDown step (editor.js:1535).
 * - node_modules/@earendil-works/pi-tui/dist/components/editor.d.ts — `Editor` API:
 *   `protected tui` (so a subclass can swap it); `EditorOptions` exposes only
 *   `paddingX` / `autocompleteMaxVisible` (no height knob).
 * - node_modules/@earendil-works/pi-tui/dist/components/terminal.js:373-377 —
 *   `get rows()` returns `process.stdout.rows || Number(LINES) || 24`.
 * - dist/modes/interactive/components/custom-editor.js — `CustomEditor extends Editor`,
 *   adds app keybindings (escape/interrupt, ctrl+d, model switching). Subclass this,
 *   not the base `Editor`.
 * - dist/modes/interactive/interactive-mode.js:1786 — the editor factory is invoked as
 *   `factory(this.ui, getEditorTheme(), this.keybindings)`, i.e. (tui, theme, keybindings).
 *   `setCustomEditorComponent` (:1779-1834) copies text, handlers, padding, and
 *   autocomplete onto the replacement and focuses it.
 * - dist/core/package-manager.js:540-583 (`applyPatterns`) — auto-load rule: with only
 *   `+`/`-` overrides in settings.json, every `.ts` in the extensions dir loads unless
 *   explicitly `-`'d. So this file needs no settings entry.
 * - docs/tui.md (Pattern 7: Custom Editor) and docs/extensions.md ("Custom Editor",
 *   `ctx.ui.setEditorComponent`) — the documented replace-the-editor hook.
 *
 * Doc caveat: docs/tui.md and docs/extensions.md show `new VimEditor(theme, keybindings)`,
 * dropping the `tui` arg. The real call site passes (tui, theme, keybindings); this file
 * follows the source.
 */
import { CustomEditor, type ExtensionAPI } from "@earendil-works/pi-coding-agent";

/**
 * Raise the message input box's height ceiling.
 *
 * The base Editor caps its visible height at `max(5, floor(terminalRows * 0.3))`
 * lines — a hardcoded constant in @earendil-works/pi-tui with no setting exposed.
 * The constant can't be changed from outside, but the cap is derived solely from
 * `this.tui.terminal.rows`, and `tui` is `protected`. So during render we hand the
 * base an inflated row count, which lifts the cap to ~TARGET_FRACTION of the
 * terminal — without touching the real terminal size or reimplementing render().
 *
 * Tune TARGET_FRACTION to taste (e.g. 0.5 for half the screen, 0.75 for more).
 */
const TARGET_FRACTION = 0.6;
const UPSTREAM_FRACTION = 0.3;
const ROW_INFLATION = TARGET_FRACTION / UPSTREAM_FRACTION;

class TallerEditor extends CustomEditor {
  override render(width: number): string[] {
    const realTui = this.tui;
    this.tui = new Proxy(realTui, {
      get(target, prop) {
        if (prop !== "terminal") {
          const value = Reflect.get(target, prop);
          return typeof value === "function" ? value.bind(target) : value;
        }
        return new Proxy(target.terminal, {
          get(terminal, terminalProp) {
            if (terminalProp === "rows") {
              return Math.round(terminal.rows * ROW_INFLATION);
            }
            const value = Reflect.get(terminal, terminalProp);
            return typeof value === "function" ? value.bind(terminal) : value;
          },
        });
      },
    });
    try {
      return super.render(width);
    } finally {
      this.tui = realTui;
    }
  }
}

export default function (pi: ExtensionAPI) {
  pi.on("session_start", (_event, ctx) => {
    if (ctx.mode !== "tui") return;
    ctx.ui.setEditorComponent((tui, theme, keybindings) => new TallerEditor(tui, theme, keybindings));
  });
}

